function ProductCard({ product, add, wishlist, toggleWishlist, openDetails }) {
  const viewDetails = () => openDetails(product);
  const handleCardKeyDown = (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      viewDetails();
    }
  };
  return (
    <article
      className="card"
      onClick={viewDetails}
      onKeyDown={handleCardKeyDown}
      tabIndex="0"
      role="link"
      aria-label={`View details for ${product.name}`}
    >
      <div className="product-image">
        <span className="tag">{product.tag}</span>
        <button
          className="heart"
          aria-label="Add to wishlist"
          onClick={(event) => {
            event.stopPropagation();
            toggleWishlist(product._id);
          }}
          style={{ color: wishlist ? "#9d4a45" : "#b5a075" }}
        >
          {wishlist ? "♥" : "♡"}
        </button>
        <img src={product.image} alt={product.name} />
      </div>
      <div className="details">
        <div className="category">{product.category}</div>
        <h3>{product.name}</h3>
        <div className="desc">{product.description}</div>
        <div className="weight">{product.weight}</div>
        <div className="price-row">
          <span className="price">{money(product.price)}</span>
        </div>
        <span className="saving">
          {product.name.toLowerCase().includes("ortho")
            ? "Ortho Amrit Collection"
            : "King Kesari Collection"}
        </span>
        <div className="card-actions">
          <button
            className="add"
            onClick={(event) => {
              event.stopPropagation();
              add(product);
            }}
          >
            ADD TO BAG
          </button>
          <button
            className="details-button"
            onClick={(event) => {
              event.stopPropagation();
              viewDetails();
            }}
          >
            VIEW DETAILS
          </button>
        </div>
      </div>
    </article>
  );
}
